<script setup>
import {computed,ref} from 'vue'
import Chart from './Chart.vue'
import {escape,safeUrl} from '../shared'
const props=defineProps({graph:Object,height:{default:370},compact:Boolean})
const focus=ref(null)
const labels={fund:'基金',paper:'论文',patent:'专利',technology:'技术'}
const tones={fund:'#ae1833',paper:'#367ca3',patent:'#377f70',technology:'#987aab'}
const option=computed(()=>{let g=props.graph||{nodes:[],edges:[]};if(props.compact){const keep=new Set(['AI1.01','AI1.02','AI3.07','AI5.03','AI5.01','AI2.04','AI1.06','AI2.11']);const edges=g.edges.filter(e=>keep.has(e.target)||e.kind==='source_project_id');const ids=new Set(edges.flatMap(e=>[e.source,e.target]));g={nodes:g.nodes.filter(n=>ids.has(n.id)),edges};}const cols=['fund','paper','technology','patent'];let placed=[];for(const [i,type] of cols.entries()){let ns=g.nodes.filter(n=>n.type===type);placed.push(...ns.map((n,j)=>({...n,x:60+i*240,y:35+j*(310/Math.max(1,ns.length-1)),name:n.label.length>12?n.label.slice(0,12)+'…':n.label,value:n.label,symbolSize:type==='technology'?23:type==='fund'?21:18,itemStyle:{color:tones[type]},label:{show:true,position:type==='technology'?'right':'bottom',fontSize:12,fontWeight:550,color:'#455366',width:type==='technology'?120:145,overflow:'truncate',backgroundColor:'#ffffffdf',padding:[2,3],borderRadius:3}})))}return {animationDuration:650,tooltip:{trigger:'item',confine:true,formatter:p=>p.dataType==='edge'?escape(p.data.label):`${escape(labels[p.data.type])}<br/><b>${escape(p.data.value)}</b>`},series:[{type:'graph',layout:'none',roam:true,draggable:true,left:70,right:80,top:38,bottom:50,emphasis:{focus:'adjacency',lineStyle:{width:3},label:{show:true}},lineStyle:{opacity:.45,color:'source',curveness:.14,width:1.6},data:placed,links:g.edges.map(e=>({...e,lineStyle:{type:e.kind==='source_project_id'?'solid':'dashed'}}))}]}})
function select(p){focus.value=p.dataType==='edge'?{...p.data,isEdge:true}:p.data}
</script>
<template><div class="research-network"><div class="network-key"><span v-for="[key,label] in Object.entries(labels)" :key="key"><i :style="{background:tones[key]}"></i>{{label}}</span><small>关系样本</small></div><Chart :option="option" :height="height" label="基金、论文、技术、专利多链关系图" @select="select"/><div class="network-selection" aria-live="polite"><template v-if="focus"><b>{{focus.isEdge?focus.label:focus.value}}</b><span v-if="focus.isEdge">{{focus.evidence?.[0]?.snippet}}</span><span v-else>{{focus.fields?.['批准号']||focus.fields?.['作者']||focus.source}}</span><a v-if="focus.url" :href="safeUrl(focus.url)" target="_blank" rel="noopener">原始文献 ↗</a></template><template v-else>悬停聚焦关联 · 点击节点或连线查看依据 · 拖动与缩放探索</template></div></div></template>
